"use client";

/** The shape of a list that has not arrived yet.
 *
 * Two exports because a list is loaded in two different situations and
 * they need different markup:
 *
 * - **`TableSkeleton`** stands where a table will be, on the pages that
 *   render nothing at all until the fetch lands.
 * - **`SkeletonRows`** goes inside a `<tbody>` that is already on screen,
 *   which is the library's case: its header renders immediately and only
 *   the rows are missing.
 *
 * **Every bar has a real height, and the block has the row count it will
 * be replaced by.** A skeleton that collapses to nothing is worse than
 * the word "Loading": the page settles at one height, then grows under
 * the reader's cursor the moment the data lands. Height is the entire
 * reason this exists - the shimmer is decoration.
 *
 * It keeps `role="status"` and the same `common.loading` string the text
 * it replaces used, so a screen reader is told the same thing it was
 * told before. A shimmering rectangle announces nothing on its own.
 */

import type { CSSProperties } from "react";

/** Widths that repeat down the column, so rows do not look stamped.
 *
 * Deliberately fixed rather than random: a random width re-rolls on
 * every render, and a skeleton that flickers while it waits reads as a
 * fault rather than as waiting.
 */
const WIDTHS = ["82%", "64%", "91%", "73%", "58%"] as const;

function columnStyle(columns: number): CSSProperties {
  // The count travels as a custom property rather than as a full
  // `grid-template-columns` string: the layout rule stays in the
  // stylesheet where the rest of the table's spacing lives.
  return { "--skeleton-columns": columns } as CSSProperties;
}

export function TableSkeleton({
  columns,
  rows = 4,
  label,
}: {
  /** How many the real table has, so the bars line up with its columns. */
  columns: number;
  rows?: number;
  /** Already translated; callers pass `t("common.loading")`. */
  label: string;
}) {
  return (
    <div className="panel table-skeleton" role="status" aria-label={label} style={columnStyle(columns)}>
      {Array.from({ length: rows }, (_, row) => (
        <div className="table-skeleton-row" key={row}>
          {Array.from({ length: columns }, (_, column) => (
            <span
              className="skeleton table-skeleton-cell"
              key={column}
              style={{ width: WIDTHS[(row + column) % WIDTHS.length] }}
            />
          ))}
        </div>
      ))}
    </div>
  );
}

export function SkeletonRows({
  columns,
  rows = 4,
  label,
}: {
  columns: number;
  rows?: number;
  label: string;
}) {
  return (
    <>
      {Array.from({ length: rows }, (_, row) => (
        <tr className="skeleton-row" key={row} aria-hidden={row > 0 ? "true" : undefined}>
          {Array.from({ length: columns }, (_, column) => (
            <td key={column}>
              <span
                className="skeleton table-skeleton-cell"
                // Only the first row carries the announcement; five rows
                // each saying "loading" is five announcements for one
                // wait.
                role={row === 0 && column === 0 ? "status" : undefined}
                aria-label={row === 0 && column === 0 ? label : undefined}
                style={{ width: WIDTHS[(row + column) % WIDTHS.length] }}
              />
            </td>
          ))}
        </tr>
      ))}
    </>
  );
}
