"use client";

/** A failure the reader can act on, rather than one they can only read.
 *
 * Forty-odd surfaces reported errors and two offered a way out; the rest
 * left a reload of the whole page as the only move, which on a page with
 * unsaved work costs the work. A retry that re-runs the same fetch is
 * the difference between a message and a control.
 *
 * `onRetry` is optional on purpose. Some failures are not retryable - a
 * rejected upload, a validation refusal - and a button that re-sends
 * something the server already refused teaches the reader that the
 * button does nothing. Callers pass it only where retrying is the right
 * next act.
 *
 * `role="alert"` rather than `status`: this interrupts. It is the one
 * place in the app where taking the reader's attention is correct.
 */

import { useTranslation } from "@/lib/i18n";

export function ErrorBox({
  message,
  onRetry,
  busy = false,
}: {
  message: string;
  /** Omit where retrying cannot help. */
  onRetry?: () => void;
  /** Disables the button while the retry is in flight, so a reader who
   *  clicks twice does not queue a second request behind the first. */
  busy?: boolean;
}) {
  const { t } = useTranslation();
  return (
    <div className="error-box" role="alert">
      <span>{message}</span>
      {onRetry ? (
        <button type="button" onClick={onRetry} disabled={busy}>
          {t("common.retry")}
        </button>
      ) : null}
    </div>
  );
}
